-- Hostel Room Allocation and Management System
-- Oracle SQL starter: 7 core tables + 4 additional tables.
-- IMPORTANT: Run ONLY in a new/empty schema. Do not run on your existing schema without comparing it.
-- Sample records are fictional. Backend mappings/frontend must be updated for added columns and tables.
SET DEFINE OFF;

CREATE TABLE STUDENTS (
 STUDENT_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 REG_NO VARCHAR2(20) NOT NULL UNIQUE, NAME VARCHAR2(100) NOT NULL,
 DEPARTMENT VARCHAR2(100) NOT NULL, YEAR_OF_STUDY NUMBER(1) NOT NULL CHECK (YEAR_OF_STUDY BETWEEN 1 AND 6),
 PHONE VARCHAR2(20), EMAIL VARCHAR2(150) NOT NULL UNIQUE, DATE_OF_BIRTH DATE,
 GENDER VARCHAR2(20), ADDRESS VARCHAR2(300), EMERGENCY_CONTACT_NAME VARCHAR2(100),
 EMERGENCY_CONTACT_PHONE VARCHAR2(20), CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE HOSTELS (
 HOSTEL_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, HOSTEL_NAME VARCHAR2(100) NOT NULL UNIQUE,
 HOSTEL_TYPE VARCHAR2(30) NOT NULL, LOCATION VARCHAR2(200) NOT NULL, WARDEN_NAME VARCHAR2(100),
 WARDEN_PHONE VARCHAR2(20), TOTAL_FLOORS NUMBER(3) DEFAULT 1 NOT NULL CHECK (TOTAL_FLOORS > 0),
 GENDER_CATEGORY VARCHAR2(20), STATUS VARCHAR2(20) DEFAULT 'Active' NOT NULL CHECK (STATUS IN ('Active','Maintenance','Closed'))
);
CREATE TABLE ROOM_TYPES (
 TYPE_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, TYPE_NAME VARCHAR2(50) NOT NULL UNIQUE,
 CAPACITY NUMBER(2) NOT NULL CHECK (CAPACITY > 0), HOSTEL_FEE NUMBER(10,2) NOT NULL CHECK (HOSTEL_FEE >= 0),
 DESCRIPTION VARCHAR2(300), AC_AVAILABLE CHAR(1) DEFAULT 'N' CHECK (AC_AVAILABLE IN ('Y','N')),
 ATTACHED_BATHROOM CHAR(1) DEFAULT 'N' CHECK (ATTACHED_BATHROOM IN ('Y','N'))
);
CREATE TABLE ROOMS (
 ROOM_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, HOSTEL_ID NUMBER NOT NULL REFERENCES HOSTELS(HOSTEL_ID),
 TYPE_ID NUMBER NOT NULL REFERENCES ROOM_TYPES(TYPE_ID), ROOM_NUMBER VARCHAR2(20) NOT NULL,
 FLOOR_NUMBER NUMBER(3) NOT NULL CHECK (FLOOR_NUMBER >= 0),
 ROOM_STATUS VARCHAR2(20) DEFAULT 'Available' NOT NULL CHECK (ROOM_STATUS IN ('Available','Occupied','Maintenance','Unavailable')),
 CAPACITY NUMBER(2) NOT NULL CHECK (CAPACITY > 0), MONTHLY_FEE NUMBER(10,2) NOT NULL CHECK (MONTHLY_FEE >= 0),
 AC_AVAILABLE CHAR(1) DEFAULT 'N' CHECK (AC_AVAILABLE IN ('Y','N')), NOTES VARCHAR2(500),
 CONSTRAINT UQ_ROOM_PER_HOSTEL UNIQUE (HOSTEL_ID, ROOM_NUMBER)
);
CREATE TABLE APPLICATIONS (
 APPLICATION_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, STUDENT_ID NUMBER NOT NULL REFERENCES STUDENTS(STUDENT_ID),
 APPLICATION_DATE DATE DEFAULT SYSDATE NOT NULL, PREFERRED_TYPE_ID NUMBER NOT NULL REFERENCES ROOM_TYPES(TYPE_ID),
 PREFERRED_HOSTEL_ID NUMBER REFERENCES HOSTELS(HOSTEL_ID),
 STATUS VARCHAR2(20) DEFAULT 'Pending' NOT NULL CHECK (STATUS IN ('Pending','Approved','Rejected','Waitlisted','Cancelled')),
 PRIORITY_LEVEL VARCHAR2(20) DEFAULT 'Normal' NOT NULL CHECK (PRIORITY_LEVEL IN ('Low','Normal','High')),
 REVIEWED_BY VARCHAR2(100), REVIEW_DATE DATE, REJECTION_REASON VARCHAR2(500), NOTES VARCHAR2(500)
);
CREATE TABLE ALLOCATIONS (
 ALLOCATION_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, APPLICATION_ID NUMBER NOT NULL UNIQUE REFERENCES APPLICATIONS(APPLICATION_ID),
 ROOM_ID NUMBER NOT NULL REFERENCES ROOMS(ROOM_ID), ALLOCATION_DATE DATE DEFAULT SYSDATE NOT NULL,
 CHECK_IN_DATE DATE, EXPECTED_CHECK_OUT DATE, ACTUAL_CHECK_OUT DATE,
 STATUS VARCHAR2(20) DEFAULT 'Active' NOT NULL CHECK (STATUS IN ('Active','Pending','Completed','Cancelled')),
 MONTHLY_FEE NUMBER(10,2) NOT NULL CHECK (MONTHLY_FEE >= 0), NOTES VARCHAR2(500),
 CONSTRAINT CK_ALLOCATION_DATES CHECK (EXPECTED_CHECK_OUT IS NULL OR CHECK_IN_DATE IS NULL OR EXPECTED_CHECK_OUT >= CHECK_IN_DATE)
);
CREATE TABLE PAYMENTS (
 PAYMENT_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ALLOCATION_ID NUMBER NOT NULL REFERENCES ALLOCATIONS(ALLOCATION_ID),
 AMOUNT NUMBER(10,2) NOT NULL CHECK (AMOUNT > 0), PAYMENT_DATE DATE DEFAULT SYSDATE NOT NULL,
 PAYMENT_STATUS VARCHAR2(20) DEFAULT 'Pending' NOT NULL CHECK (PAYMENT_STATUS IN ('Paid','Pending','Failed','Refunded')),
 PAYMENT_METHOD VARCHAR2(30) NOT NULL, RECEIPT_NUMBER VARCHAR2(40) UNIQUE,
 TRANSACTION_REFERENCE VARCHAR2(100), DUE_DATE DATE, REMARKS VARCHAR2(500)
);
CREATE TABLE COMPLAINTS (
 COMPLAINT_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, STUDENT_ID NUMBER NOT NULL REFERENCES STUDENTS(STUDENT_ID),
 ROOM_ID NUMBER REFERENCES ROOMS(ROOM_ID), CATEGORY VARCHAR2(50) NOT NULL, DESCRIPTION VARCHAR2(1000) NOT NULL,
 PRIORITY VARCHAR2(20) DEFAULT 'Medium' NOT NULL CHECK (PRIORITY IN ('Low','Medium','High','Urgent')),
 STATUS VARCHAR2(20) DEFAULT 'Open' NOT NULL CHECK (STATUS IN ('Open','In Progress','Resolved','Closed')),
 CREATED_AT DATE DEFAULT SYSDATE NOT NULL, RESOLVED_AT DATE, ASSIGNED_TO VARCHAR2(100), RESOLUTION_NOTES VARCHAR2(1000)
);
CREATE TABLE VISITORS (
 VISITOR_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, STUDENT_ID NUMBER NOT NULL REFERENCES STUDENTS(STUDENT_ID),
 VISITOR_NAME VARCHAR2(100) NOT NULL, RELATIONSHIP VARCHAR2(50), PHONE VARCHAR2(20), PURPOSE VARCHAR2(500),
 ENTRY_TIME TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, EXIT_TIME TIMESTAMP, VERIFIED_BY VARCHAR2(100), ID_TYPE VARCHAR2(30),
 VISIT_STATUS VARCHAR2(20) DEFAULT 'Checked In' NOT NULL CHECK (VISIT_STATUS IN ('Checked In','Checked Out','Denied')),
 CONSTRAINT CK_VISITOR_TIME CHECK (EXIT_TIME IS NULL OR EXIT_TIME >= ENTRY_TIME)
);
CREATE TABLE ATTENDANCE (
 ATTENDANCE_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, STUDENT_ID NUMBER NOT NULL REFERENCES STUDENTS(STUDENT_ID),
 ATTENDANCE_DATE DATE NOT NULL, CHECK_IN_TIME TIMESTAMP, CHECK_OUT_TIME TIMESTAMP,
 STATUS VARCHAR2(20) NOT NULL CHECK (STATUS IN ('Present','Absent','Late','On Leave')), REMARKS VARCHAR2(500),
 RECORDED_BY VARCHAR2(100), CONSTRAINT UQ_STUDENT_ATTENDANCE UNIQUE (STUDENT_ID, ATTENDANCE_DATE)
);
CREATE TABLE ROOM_INSPECTIONS (
 INSPECTION_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ROOM_ID NUMBER NOT NULL REFERENCES ROOMS(ROOM_ID),
 INSPECTION_DATE DATE DEFAULT SYSDATE NOT NULL, INSPECTED_BY VARCHAR2(100) NOT NULL,
 CLEANLINESS_SCORE NUMBER(2) CHECK (CLEANLINESS_SCORE BETWEEN 1 AND 10),
 SAFETY_SCORE NUMBER(2) CHECK (SAFETY_SCORE BETWEEN 1 AND 10), ISSUES_FOUND VARCHAR2(1000),
 ACTION_REQUIRED VARCHAR2(1000), STATUS VARCHAR2(20) DEFAULT 'Pending' NOT NULL
 CHECK (STATUS IN ('Pending','In Progress','Completed')), NEXT_INSPECTION_DATE DATE
);

